import type { Readable } from "node:stream";

/**
 * Where uploaded files live. Metadata is in PostgreSQL; the bytes are here. Keys are generated by the server
 * (never from user input), e.g. `conversations/<conversationId>/<uuid>.png`.
 */
export interface Storage {
  put(key: string, data: Buffer): Promise<void>;
  /** The object's size, or null when it does not exist. */
  stat(key: string): Promise<{ size: number } | null>;
  /** Streams the object, or a byte range of it (both ends inclusive). */
  open(key: string, range?: { start: number; end: number }): Readable;
  /** Removing an object that is already gone is not an error. */
  delete(key: string): Promise<void>;
}
